import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, Vector3, PerspectiveCamera } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, float, vec2, noise, fract, pow } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-features-card-1-label';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const ink = new THREE.Color(colors.ink);
  const paper = new THREE.Color(colors.paper);
  const accent = new THREE.Color(colors.accent);
  const surface = new THREE.Color(colors.surface);

  // ---- Backdrop: engineered vertical gradient stage ----
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const gradT = uv().y;
  const grad = mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), gradT));
  // subtle engineered accent band near top quarter
  const band = smoothstep(float(0.55), float(0.72), gradT).sub(smoothstep(float(0.72), float(0.88), gradT));
  const graded = mix(grad, vec3(accent).mul(0.12), band);
  // subtle grain
  const grainSeed = fract(uv().mul(vec2(512, 320)).add(time.mul(0.05)));
  const grain = noise(grainSeed.mul(0.5)).sub(float(0.5)).mul(0.025);
  backdropMat.colorNode = graded.add(grain);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---- Textured image card (the asset plane) ----
  const cardW = 2.4, cardH = 1.5;
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH);
  const cardMat = new THREE.MeshStandardNodeMaterial({
    colorNode: vec3(paper),
    roughness: 0.55,
    metalness: 0.45,
    transparent: true,
  });
  // overlay image via map node when loaded
  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.set(0, -0.15, 0.02);
  card.castShadow = true;
  group.add(card);

  // Load the image texture and apply
  let tex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      tex = t;
      cardMat.map = t;
      // blend: paper base + image overlay
      cardMat.colorNode = mix(vec3(paper).mul(0.85), vec3(1.0), float(1.0));
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- Card frame: thin accent rule on left edge ----
  const ruleGeo = new THREE.PlaneGeometry(0.04, cardH * 0.9);
  const ruleMat = new THREE.MeshBasicNodeMaterial({ color: accent, transparent: true });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-cardW / 2 + 0.04, -0.15, 0.05);
  group.add(rule);

  // ---- Contact shadow under card ----
  const shadowGeo = new THREE.PlaneGeometry(cardW * 1.5, cardH * 0.6);
  const shadowMat = new THREE.MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sUv = uv().sub(vec2(0.5, 0.5));
  const sFade = pow(float(1.0).sub(sUv.length().mul(1.4)), float(2.0));
  shadowMat.colorNode = vec3(0.0).mul(0.0);
  shadowMat.opacityNode = sFade.mul(0.5);
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -cardH / 2 - 0.1, -0.05);
  shadow.rotation.x = -0.18;
  group.add(shadow);

  // ---- Text label "Features 1" ----
  const headlineItem = items.find(i => i.role === 'headline') || items[0];
  const headlineText = headlineItem?.text ?? 'Features 1';
  const headlineSize = (headlineItem?.typography?.fontSize ?? 39) / 100;
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineItem?.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-cardW / 2 + 0.12, cardH / 2 - 0.05, 0.06);
  group.add(headline);

  // small index caption
  const caption = ctx.fontAtlas.createText('01', {
    fontSize: 14,
    color: colors.accent,
    align: 'left',
  });
  caption.position.set(cardW / 2 - 0.18, cardH / 2 - 0.05, 0.06);
  group.add(caption);

  // ---- Lighting (node-local accents on top of scene ambient) ----
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(2.2, 2.0, 3.0);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(accent.getHex(), 0.7);
  rimLight.position.set(-2.5, 0.8, -1.5);
  group.add(rimLight);

  const fillLight = new THREE.HemisphereLight(paper.getHex(), surface.getHex(), 0.4);
  group.add(fillLight);

  // ---- Subtle idle breathing (single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(card.position, { y: -0.12, duration: 4.2, ease: 'sine.inOut' });
  idleTl.to(card.position, { y: -0.18, duration: 4.2, ease: 'sine.inOut' });

  // ---- Entrance: rise-in ----
  const enterTl = gsap.timeline();
  group.position.y = 0.4;
  group.scale.set(0.98, 0.98, 1);
  enterTl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  enterTl.to(group.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }, 0);
  enterTl.fromTo(headline.position, { z: 0.02 }, { z: 0.06, duration: 0.5, ease: 'power2.out' }, 0.1);

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    idleTl.kill();
    enterTl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (tex) tex.dispose && tex.dispose();
  };

  group.userData.handlers = {};

  return group;
}
